#define _XOPEN_SOURCE 700

#include <errno.h>
#include <locale.h>
#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include "debug.h"
#include "fileio.h"
#include "platform.h"
#include "util.h"

/* ISO C wants a declaration even when the option is built out. */
typedef int debug_unit;

#ifdef CSM_DEBUG

static FILE *log_fp;
static char *log_path;

static void env(const char *name)
{
	const char *value = getenv(name);

	debug_log("env %s=%s", name, value != NULL ? value : "(unset)");
}

/*
 * Opens debug.log next to the trash, appending: one file for every run,
 * outside the repositories being moved and outside Claude Code's data.
 * -1 with errno when it cannot be opened.
 */
int debug_open(int argc, char **argv)
{
	char *dir, *cwd;
	int i;

	dir = platform_data_dir(getenv("HOME"));
	if (dir == NULL) {
		errno = ENOENT;
		return -1;
	}
	if (dir_make(dir, 0700) != 0) {
		free(dir);
		return -1;
	}
	log_path = xjoin(dir, "debug.log");
	free(dir);
	log_fp = fopen(log_path, "a");
	if (log_fp == NULL)
		return -1;
	debug_log("---- csm started, pid %ld, uid %ld", (long)getpid(),
	    (long)getuid());
	for (i = 0; i < argc; i++)
		debug_log("argv[%d]=%s", i, argv[i]);
	cwd = xgetcwd();
	debug_log("cwd %s", cwd != NULL ? cwd : "(unknown)");
	free(cwd);
	env("HOME");
	env("CLAUDE_CONFIG_DIR");
	env("LANG");
	env("LC_ALL");
	env("TERM");
	debug_log("locale LC_CTYPE=%s", setlocale(LC_CTYPE, NULL));
	return 0;
}

const char *debug_path(void)
{
	return log_path;
}

/* One line with the local time in milliseconds, written at once. */
void debug_log(const char *fmt, ...)
{
	struct timespec ts;
	struct tm tm;
	char stamp[32];
	va_list ap;
	int saved = errno;

	if (log_fp == NULL)
		return;
	clock_gettime(CLOCK_REALTIME, &ts);
	localtime_r(&ts.tv_sec, &tm);
	strftime(stamp, sizeof stamp, "%Y-%m-%d %H:%M:%S", &tm);
	fprintf(log_fp, "%s.%03ld ", stamp, ts.tv_nsec / 1000000);
	va_start(ap, fmt);
	vfprintf(log_fp, fmt, ap);
	va_end(ap);
	fputc('\n', log_fp);
	fflush(log_fp);
	errno = saved;
}

void debug_close(void)
{
	if (log_fp != NULL) {
		debug_log("---- csm finished");
		fclose(log_fp);
	}
	log_fp = NULL;
	free(log_path);
	log_path = NULL;
}

#endif
